function sanitizeFirebase(value,path,media){
  if(Array.isArray(value))return value.map(function(v,i){return sanitizeFirebase(v,path+"["+i+"]",media);});
  if(value&&typeof value==="object"){
    const out={};
    for(const k of Object.keys(value)){
      const v=value[k];
      if(typeof v==="string"&&(/^data:image\//i.test(v)||v.length>15000)){
        media.push({path:path?path+"."+k:k,bytes:v.length,kind:/portrait/i.test(k)?"portrait":(/photo/i.test(k)?"photo":"large-string")});
        out[k]="[MEDIA_OMITTED_FROM_FAST_BACKUP]";
      }else out[k]=sanitizeFirebase(v,path?path+"."+k:k,media);
    }
    return out;
  }
  return value;
}
async function firebaseExport(env,idToken){
  const nodes=["diplomaData","publicDiplomaData","downloadLogs","securityLogs","portraitRequests"];
  const data={},media=[],errors=[];
  for(const node of nodes){
    try{
      const r=await fetch(env.FIREBASE_DATABASE_URL+"/"+node+".json?auth="+encodeURIComponent(idToken),{headers:{"cache-control":"no-store"}});
      if(!r.ok){errors.push(node+": HTTP "+r.status);continue;}
      data[node]=sanitizeFirebase(await r.json(),node,media);
    }catch(e){errors.push(node+": "+(e&&e.message?e.message:String(e)));}
  }
  return {data:data,media:media,errors:errors};
}
async function d1Export(env){
  const tablesRes=await env.DB.prepare("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all();
  const excludedTables=new Set(["_cf_KV","admin_tokens","student_sessions","video_tickets","student_login_attempts"]);
  const tables=(tablesRes.results||[]).filter(function(x){
    return /^[A-Za-z0-9_]+$/.test(x.name) && !excludedTables.has(x.name);
  });
  const schema=tables.map(function(t){return t.sql;}).filter(Boolean).join(";\n\n")+";\n";
  const out={};
  for(const t of tables){
    const rows=[];let offset=0;
    while(true){
      const q=await env.DB.prepare('SELECT * FROM "'+t.name+'" LIMIT 1000 OFFSET ?').bind(offset).all();
      const batch=q.results||[];rows.push.apply(rows,batch);
      if(batch.length<1000)break;
      offset+=1000;if(offset>100000)break;
    }
    out[t.name]=rows;
  }
  return {schema:schema,tables:out};
}
async function fetchBytes(url){
  const r=await fetch(url,{headers:{"user-agent":"KMT-Master-Backup/1.0","cache-control":"no-store"}});
  if(!r.ok)throw new Error(url+" HTTP "+r.status);
  return new Uint8Array(await r.arrayBuffer());
}
async function repoHead(repo){
  try{
    const r=await fetch("https://api.github.com/repos/"+repo+"/commits/main",{headers:{"user-agent":"KMT-Master-Backup/1.0"}});
    if(!r.ok)return null;
    const d=await r.json();return {sha:d.sha,date:d.commit&&d.commit.committer?d.commit.committer.date:null};
  }catch(e){return null;}
}
